<?php require_once __DIR__.'/config/database.php'; require_once __DIR__.'/config/auth.php'; require_once __DIR__.'/config/helpers.php'; require_login('teacher'); $page_title='Attendance reports'; $date=trim($_GET['date']??''); $sql="SELECT s.id,s.subject,s.session_date,COUNT(a.id) present_count,(SELECT COUNT(*) FROM students) total_students FROM attendance_sessions s LEFT JOIN attendance a ON a.session_id=s.id WHERE s.teacher_id=?"; $params=[current_user()['id']]; if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){ $sql.=' AND s.session_date=?'; $params[]=$date; } else $date=''; $sql.=' GROUP BY s.id ORDER BY s.session_date DESC,s.id DESC'; $st=db()->prepare($sql); $st->execute($params); $rows=$st->fetchAll(); ?>
<?php include __DIR__.'/partials/header.php'; ?><div class="container reveal"><section class="panel"><div class="panel-head"><div><h3>Date-wise attendance report</h3><span>Session attendance and participation rate</span></div><form method="get" style="display:flex;gap:7px"><input type="date" name="date" value="<?=e($date)?>" style="padding:8px;border:1px solid var(--border);border-radius:9px;background:var(--surface);color:var(--text)"><button class="btn btn-secondary">Filter</button></form></div><div class="table-wrap"><?php if($rows): ?><table><thead><tr><th>Date</th><th>Subject</th><th>Present</th><th>Total</th><th>Rate</th><th></th></tr></thead><tbody><?php foreach($rows as $r): $total=intval($r['total_students']); $count=intval($r['present_count']); $rate=$total?round($count/$total*100):0; ?><tr><td><?=e(date('d M Y',strtotime($r['session_date'])))?></td><td><strong><?=e($r['subject'])?></strong></td><td><?=$count?></td><td><?=$total?></td><td><div class="progress"><span style="width:<?=$rate?>%"></span></div><small style="color:var(--muted)"><?=$rate?>%</small></td><td><a class="btn btn-secondary" href="attendance_qr.php?id=<?=intval($r['id'])?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php else: ?><div class="empty"><div class="empty-icon">▤</div><strong>No report data</strong></div><?php endif; ?></div></section></div><?php include __DIR__.'/partials/footer.php'; ?>